package nl.trusttech.service;

import nl.trusttech.models.AndroidAttestationResult;
import org.junit.jupiter.api.Test;
import org.multipaz.asn1.*;
import java.io.*;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

public class AttestationTest {
    public static String iosAttestation = "";
    public static String androidAttestation = "";

    public static Map<String, String> deviceKeyJwk = Map.of(
            "kty", "EC",
            "crv", "P-256",
            "x", "SdEzDu6ivx1Uc1xo5VnVH-z-DivAJRAemLh1b-ZtsU0",
            "y", "RFnxbKEAF-hhoSgGnmD9jwQh3xaQIkp3ZRMbxgePV6Y"
    );

    private static final AndroidAttestationService androidAttestationService = new AndroidAttestationService();
    private static final IosAttestationService iosAttestationService = new IosAttestationService();

    @Test
    void decompileAppAttest() {
        Map<String, Object> response = iosAttestationService.checkIosAttest(iosAttestation);

        assertNotNull(response.get("notBefore"));
        assertNotNull(response.get("notAfter"));
        assertEquals("64SX4L8SX7.com.merck.wallet", response.get("appId"));
        assertEquals("ATTEST", response.get("receiptType"));
        assertEquals("production", response.get("environment"));
    }

    @Test
    void checkAndroidAttestTest() throws Exception {
        AndroidAttestationResult response = androidAttestationService.checkAndroidAttest(androidAttestation, deviceKeyJwk);
        assertEquals("nl.trusttech.walletapp", response.packageName);
        assertTrue(response.certificateChainValid);
        assertTrue(response.publicKeyMatched);

        assertEquals("TEE", response.securityLevel);
        assertEquals("KM_ORIGIN_GENERATED", response.keyOrigin);
    }
}
